macro.command:
// 物品：postActiveEffects；庇护 AE：isTargeted、preAttackRoll、postActiveEffects。
const pass = args[0]?.macroPass;
if (!["postActiveEffects", "isTargeted", "preAttackRoll"].includes(pass)) return;
const cast = workflow;
const marker = "sanctuary";
const effects = actor => Array.from(actor?.appliedEffects ?? actor?.effects ?? [])
  .filter(e => e.active && e.flags?.dnd5e_classpack?.automation === marker);
const remove = async (actor, list) => {
  if (list.length) await MidiQOL.socket().executeAsGM("removeEffects", {
    actorUuid: actor.uuid, effects: list.map(e => e.id)
  });
};

// 记录本次施法的 DC，避免以后施法者的属性或施法属性变化影响现有效果。
if (pass === "postActiveEffects" && cast.item.uuid === macroItem.uuid) {
  const ability = cast.activity.spellcastingAbility;
  const dc = Number(cast.actor.system.abilities[ability]?.dc);
  if (!Number.isFinite(dc)) {
    ui.notifications.warn("庇护术：无法确定本次施法的豁免 DC，请检查施法属性。");
    return;
  }
  for (const target of cast.targets) {
    const list = effects(target.actor).filter(e =>
      e.system?.origin?.message === cast.itemCardUuid);
    if (list.length) await MidiQOL.socket().executeAsGM("updateEffects", {
      actorUuid: target.actor.uuid,
      updates: list.map(e => ({ _id: e.id, "flags.dnd5e_classpack.sanctuaryDC": dc }))
    });
  }
  return;
}

if (pass !== "isTargeted") {
  const list = effects(cast.actor);
  if (!list.length) return;
  if (pass === "preAttackRoll" && cast.activity.attack) {
    await remove(cast.actor, list);
    return;
  }
  if (pass !== "postActiveEffects") return;
  const damagedAnother = (cast.damageList ?? []).some(d =>
    d.actorUuid !== cast.actor.uuid && Number(d.hpDamage ?? 0) + Number(d.tempDamage ?? 0) > 0);
  let enemyTargeted = cast.item.type === "spell" && Array.from(cast.targets).some(t =>
    t.actor?.uuid !== cast.actor.uuid && cast.token
      && t.document.disposition * cast.token.document.disposition < 0);
  const unclearTargets = cast.item.type === "spell" && !enemyTargeted && Array.from(cast.targets).some(t =>
    t.actor?.uuid !== cast.actor.uuid && (!cast.token
      || t.document.disposition * cast.token.document.disposition === 0));
  if (unclearTargets && !damagedAnother) enemyTargeted = await foundry.applications.api.DialogV2.confirm({
    window: { title: "庇护术：是否影响敌人" },
    content: "<p>这次法术是否影响了你的敌人？目标阵营为中立，无法自动判断。</p>",
    rejectClose: false
  });
  if (damagedAnother || enemyTargeted) await remove(cast.actor, list);
  return;
}

// TargetOnUse 的 actor/token 是受保护者，workflow.actor 是攻击者。
const target = args[0].options?.token;
if (!target || !cast.targets.has(target) || cast.actor.uuid === target.actor?.uuid) return;
if (cast.activity.target?.template?.type) return; // 范围效应不受庇护术限制。
const attack = !!cast.activity.attack;
let harmful = cast.item.type === "spell" && (cast.activity.type === "save"
  || (cast.activity.damage?.parts?.length ?? 0) > 0);
if (!attack && !harmful && cast.item.type === "spell") {
  harmful = await foundry.applications.api.DialogV2.confirm({
    window: { title: "庇护术" },
    content: "<p>这次是否对受保护者施放了伤害性法术？有益法术无需豁免。</p>",
    rejectClose: false
  });
}
if (!attack && !harmful) return;

cast.classpackSanctuary ??= { checked: new Set(), failed: new Set() };
const state = cast.classpackSanctuary;
let current = target;
while (current) {
  const ward = effects(current.actor)[0];
  if (!ward || state.checked.has(current.document.uuid)) break;
  const dc = Number(ward.flags.dnd5e_classpack.sanctuaryDC);
  if (!Number.isFinite(dc)) {
    ui.notifications.warn("庇护术缺少施法 DC，请重新施放庇护术后再试。");
    cast.aborted = true;
    return;
  }
  state.checked.add(current.document.uuid);
  const rolls = await cast.actor.rollSavingThrow({ ability: "wis", target: dc }, {}, {
    flavor: `庇护术：攻击 ${current.name} 前的感知豁免（DC ${dc}）`
  });
  const roll = Array.isArray(rolls) ? rolls[0] : rolls;
  // 关闭掷骰对话框不视为豁免成功。
  if (roll && Number(roll.total) >= dc) break;
  state.failed.add(current.document.uuid);
  const remaining = new Set(cast.targets);
  remaining.delete(current);
  const candidates = canvas.tokens.placeables.filter(t => t.actor && t.visible
    && !state.failed.has(t.document.uuid) && !remaining.has(t)
    && (!cast.token || MidiQOL.checkActivityRange(cast.activity, cast.token, new Set([t]), false).result !== "fail"));
  const [replacement] = candidates.length
    ? await dnd5eClasspack.dialogUtils.selectTargetDialog("庇护术：改选目标",
      "豁免未通过。选择另一个合法目标，或取消并失去对该目标的攻击／法术。",
      candidates, { skipDeadAndUnconscious: false }) : [];
  if (replacement) remaining.add(replacement);
  cast.setTargets(remaining);
  MidiQOL.updateUserTargets(Array.from(remaining, t => t.id));
  if (!remaining.size) {
    // 已使用的资源保留；只终止本次后续攻击、伤害和效果。
    cast.aborted = true;
    ui.notifications.info("庇护术：未改选目标，本次攻击／法术失去目标。");
    return;
  }
  current = replacement;
}
